CREATE TABLE IF NOT EXISTS aoo_rank_season(id VARCHAR(64) PRIMARY KEY, period_type VARCHAR(16) NOT NULL, starts_at TIMESTAMP(6) NOT NULL, ends_at TIMESTAMP(6) NOT NULL, state VARCHAR(16) NOT NULL, CHECK(period_type IN ('DAILY','WEEKLY','SEASON')), CHECK(state IN ('ACTIVE','FROZEN','CLOSED')));
CREATE TABLE IF NOT EXISTS aoo_rank_score(season_id VARCHAR(64) NOT NULL, player_id BIGINT NOT NULL, score BIGINT NOT NULL, updated_at TIMESTAMP(6) NOT NULL, PRIMARY KEY(season_id,player_id), FOREIGN KEY(season_id) REFERENCES aoo_rank_season(id));
CREATE INDEX IF NOT EXISTS ix_rank_page ON aoo_rank_score(season_id,score DESC,player_id ASC);
CREATE TABLE IF NOT EXISTS aoo_achievement_definition(code VARCHAR(64) PRIMARY KEY, target_value BIGINT NOT NULL, reward_kind VARCHAR(16) NOT NULL, reward_code VARCHAR(64) NOT NULL, reward_amount BIGINT NOT NULL, enabled BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS aoo_achievement_progress(player_id BIGINT NOT NULL, achievement_code VARCHAR(64) NOT NULL, progress BIGINT NOT NULL, updated_at TIMESTAMP(6) NOT NULL, PRIMARY KEY(player_id,achievement_code), FOREIGN KEY(achievement_code) REFERENCES aoo_achievement_definition(code));
CREATE TABLE IF NOT EXISTS aoo_achievement_claim(player_id BIGINT NOT NULL, achievement_code VARCHAR(64) NOT NULL, business_id VARCHAR(160) NOT NULL UNIQUE, claimed_at TIMESTAMP(6) NOT NULL, PRIMARY KEY(player_id,achievement_code));
